class Agreement extends StatelessWidget {



  Widget build(BuildContext context) {
    return SafeArea(
        child: new Scaffold(
            appBar: new AppBar(
              title: const Text('Agreement'),
              actions: [
                new FlatButton(
                    onPressed: () {
                      Navigator
                          .of(context)
                          .pop('User Agreed');
                    },
                    child: new Text('AGREE',
                        style: Theme
                            .of(context)
                            .textTheme
                            .subhead
                            .copyWith(color: Colors.white))),
              ],
            ),
            backgroundColor: Colors.white,
            body: SingleChildScrollView(
              child: Html(
                data: htmlData,
                onLinkTap: (url) {
                  print("Opening $url...");
                 Navigator.push(context, MaterialPageRoute(builder:(context)=>  LoadHTMLFileToWEbView(url)));
                },
                onImageTap: (src) {
                  print(src);
                },
                onImageError: (exception, stackTrace) {
                  print(exception);
                },
              ),
            ),
        ));
  }

}
class LoadHTMLFileToWEbView extends StatefulWidget {
  final String url;
  LoadHTMLFileToWEbView(this.url);
  @override
  _LoadHTMLFileToWEbViewState createState() => _LoadHTMLFileToWEbViewState();
}

class _LoadHTMLFileToWEbViewState extends State<LoadHTMLFileToWEbView> {
  @override
  Widget build(BuildContext context) {
    return FutureBuilder<String>(
      future: _loadLocalHTML(),
      builder: (context, snapshot) {
        if (snapshot.hasData) {
          return WebviewScaffold(
            appBar: AppBar(title: Text("Navigation")),
            withJavascript: true,
            appCacheEnabled: true,
            url: widget.url,
          );
        } else if (snapshot.hasError) {
          return Scaffold(
            body: Center(
              child: Text("${snapshot.error}"),
            ),
          );
        }
        return Scaffold(
          body: Center(child: CircularProgressIndicator()),
        );
      },
    );
  }
}

Future<String> _loadLocalHTML() async {
  return await rootBundle.loadString('web/agreement.html');
}